import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Avatar, Box, Card, CardContent, CardHeader, CardMedia, Typography, Grid } from '@mui/material';
import { formatDistanceToNow } from 'date-fns';
import { fr } from 'date-fns/locale';
import LikeButton from '../Likes/LikeButton';
import CommentIcon from '@mui/icons-material/Comment';
import { Publication } from '../../types';

interface PublicationCardProps {
    publication: Publication;
    currentUserId: number;
}

const PublicationCard: React.FC<PublicationCardProps> = ({ publication, currentUserId }) => {
    const navigate = useNavigate();

    // Chemins locaux vers les icônes
    const avatarUrl = publication.photo_profil
        ? `/icons/${publication.photo_profil}`
        : '/icons/green.jpg';

    const photoUrl = publication.photo_publier
        ? `http://localhost:8080/uploads/${publication.photo_publier}`
        : null;

    return (
        <Card sx={{ mb: 2, borderRadius: 3, overflow: 'hidden' }}>
            {/* Header avec l'avatar et l'auteur */}
            <CardHeader
                avatar={
                    <Avatar src={avatarUrl} sx={{ width: 48, height: 48 }} />
                }
                title={`@${publication.pseudo}`}
                subheader={formatDistanceToNow(new Date(publication.date), {
                    addSuffix: true,
                    locale: fr
                })}
            />

            {/* Contenu de la publication avec image à gauche et texte à droite */}
            <CardContent sx={{ pt: 0 }}>
                <Grid container spacing={2} alignItems="center">
                    {/* Image à gauche - 206x206 */}
                    {photoUrl && (
                        <Grid item xs={12} sm={4} md={3}>
                            <Box
                                sx={{
                                    width: '100%',
                                    maxWidth: 206,
                                    height: 206,
                                    bgcolor: '#f5f5f5',
                                    borderRadius: 2,
                                    overflow: 'hidden',
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    mx: 'auto'
                                }}
                            >
                                <img
                                    src={photoUrl}
                                    alt="Publication"
                                    style={{
                                        width: '100%',
                                        height: '100%',
                                        objectFit: 'cover'
                                    }}
                                />
                            </Box>
                        </Grid>
                    )}

                    {/* Texte centré par rapport à l'image */}
                    <Grid 
                        item 
                        xs={12} 
                        sm={photoUrl ? 8 : 12} 
                        md={photoUrl ? 9 : 12}
                        sx={{
                            display: 'flex',
                            alignItems: 'center',
                            minHeight: photoUrl ? 206 : 'auto'
                        }}
                    >
                        {publication.contenu && (
                            <Typography 
                                variant="body1" 
                                sx={{
                                    width: '100%',
                                    textAlign: 'center',
                                    fontFamily: 'Poppins, sans-serif',
                                    lineHeight: 1.6,
                                    whiteSpace: 'pre-wrap',
                                    wordBreak: 'break-word'
                                }}
                            >
                                {publication.contenu}
                            </Typography>
                        )}
                    </Grid>
                </Grid>
            </CardContent>

            {/* Boutons Like et Commentaire */}
            <CardContent>
                <Box display="flex" alignItems="center" gap={2}>
                    <LikeButton
                        userId={currentUserId}
                        publicationId={publication.id}
                        initialCount={publication.nombre_like}
                    />

                    <Box
                        display="flex"
                        alignItems="center"
                        gap={0.5}
                        sx={{ cursor: 'pointer' }}
                        onClick={() => navigate(`/commentaires?pubId=${publication.id}&userId=${currentUserId}`)}
                    >
                        <CommentIcon sx={{ color: '#666' }} />
                        <Typography variant="body2" color="text.secondary">
                            {publication.nombre_commentaire}
                        </Typography>
                    </Box>
                </Box>
            </CardContent>
        </Card>
    );
};

export default PublicationCard;
